    if got_tokens[0] != "Yes":
        return False
    if exp_tokens[0] != "Yes":
        return False
    if len(got_tokens) != 1 + n:
        return False
    try:
        X = [int(x) for x in got_tokens[1:]]
    except Exception:
        return False
    for x in X:
        if not (1 <= x <= (1 << 60) - 1):
            return False
    mask, deg = _masks(n, edges)
    # Check XOR condition bit by bit on the actual integers.
    for u in range(n):
        if deg[u] >= 1:
            acc = 0
            for v in range(n):
                if (mask[u] >> v) & 1:
                    acc ^= X[v]
            if acc != 0:
                return False
    return True
